.brand { display: flex; align-items: center; gap: var(--g-spacing-2); color: var(--g-color-text-primary); text-decoration: none; font-size: 30px; font-weight: 750; letter-spacing: -1.6px; flex-shrink: 0; }
.brand-period { color: var(--g-color-text-secondary); }
.brand-mark { width: 33px; height: 33px; background: var(--g-color-base-brand); border-radius: var(--g-border-radius-m); display: flex; align-items: center; justify-content: center; gap: 3px; transform: rotate(-5deg); }
.brand-mark i { width: 3px; height: 12px; border-radius: var(--g-border-radius-xs); background: var(--g-color-text-brand-contrast); }
.brand-mark i:nth-child(2) { height: 21px; }
.brand-mark i:nth-child(3) { height: 16px; }
.header-divider { height: 22px; width: 1px; background: var(--g-color-line-generic); }
.workspace-name { color: var(--g-color-text-secondary); }
.header-actions { margin-left: auto; display: flex; align-items: center; gap: var(--g-spacing-6); }
