.page-heading h1 { letter-spacing: -1.2px; }
.page-heading p { margin-top: var(--g-spacing-3); }
.export-arrow { font-size: 19px; margin-right: var(--g-spacing-1); }
.metrics { display: grid; grid-template-columns: repeat(3, minmax(0, 1fr)); background: var(--g-color-base-background); border: 1px solid var(--g-color-line-generic); border-radius: var(--g-border-radius-xl); margin-bottom: var(--g-spacing-6); padding: var(--g-spacing-6) 0; }
.metric { padding: 0 var(--g-spacing-7); }
.metric + .metric { border-left: 1px solid var(--g-color-line-generic); }
.metric-label { display: flex; align-items: center; gap: var(--g-spacing-2); }
.series-dot { width: 7px; height: 7px; border-radius: 50%; flex-shrink: 0; }
.metric-index { margin-left: auto; font-size: 10px; color: var(--g-color-text-hint); font-variant-numeric: tabular-nums; }
.metric-value { display: flex; align-items: baseline; gap: var(--g-spacing-3); margin: var(--g-spacing-4) 0 var(--g-spacing-2); letter-spacing: -1px; }
.metric-unit { color: var(--g-color-text-secondary); font-size: 11px; letter-spacing: 0; }
.chart-card { background: var(--g-color-base-background); border: 1px solid var(--g-color-line-generic); border-radius: var(--g-border-radius-xl); overflow: hidden; }
.chart-heading { display: flex; align-items: center; justify-content: space-between; gap: var(--g-spacing-4); padding: var(--g-spacing-7) var(--g-spacing-7) var(--g-spacing-5); }
.chart-heading h2 { letter-spacing: -.4px; }
.chart-heading p { margin-top: var(--g-spacing-2); }
.chart-toolbar { display: flex; align-items: center; justify-content: space-between; gap: var(--g-spacing-3); padding: 0 var(--g-spacing-6) var(--g-spacing-5); }
.legend { display: flex; flex-wrap: wrap; gap: var(--g-spacing-2); }
.legend-button { --g-button-text-color: var(--g-color-text-secondary); }
.legend-button-hidden { opacity: .4; }
.legend-line { display: inline-block; width: 16px; height: 3px; margin-right: var(--g-spacing-2); vertical-align: middle; border-radius: var(--g-border-radius-xs); }
.date-range { color: var(--g-color-text-secondary); font-size: 12px; white-space: nowrap; }
.chart-axis-caption { margin: 0 var(--g-spacing-7) var(--g-spacing-3); font-size: 11px; color: var(--g-color-text-hint); }
.chart-container { height: 320px; margin: 0 var(--g-spacing-5) var(--g-spacing-4); --gcharts-axis-tick-color: var(--g-color-line-generic); }
.chart-footer { min-height: 58px; padding: var(--g-spacing-3) var(--g-spacing-7); border-top: 1px solid var(--g-color-line-generic); display: flex; align-items: center; justify-content: space-between; gap: var(--g-spacing-3); }
.chart-tip { color: var(--g-color-text-secondary); font-size: 12px; display: flex; align-items: center; gap: var(--g-spacing-2); }
.info-symbol { display: inline-grid; place-items: center; border: 1px solid var(--g-color-text-hint); border-radius: 50%; width: 14px; height: 14px; font-size: 10px; flex-shrink: 0; }
.bottom-grid { display: grid; grid-template-columns: 1.2fr 1fr; gap: var(--g-spacing-5); margin-top: var(--g-spacing-5); }
.insight-card, .theme-card { padding: var(--g-spacing-5) var(--g-spacing-6); border: 1px solid var(--g-color-line-generic); border-radius: var(--g-border-radius-xl); display: flex; align-items: center; gap: var(--g-spacing-4); }
.insight-card { background: var(--g-color-base-positive-light); }
.insight-icon { display: grid; place-items: center; width: 36px; height: 36px; flex-shrink: 0; border: 1px solid var(--g-color-line-positive); border-radius: var(--g-border-radius-m); color: var(--g-color-text-positive); font-size: 24px; }
.insight-title { display: flex; align-items: center; gap: var(--g-spacing-3); margin-bottom: var(--g-spacing-2); }
.growth-badge { font-size: 11px; color: var(--g-color-text-positive); background: var(--g-color-base-positive-medium); padding: var(--g-spacing-half) var(--g-spacing-2); border-radius: var(--g-border-radius-s); font-weight: 600; }
.insight-card p { line-height: 1.6; font-size: 12px; }
.theme-card { background: var(--g-color-base-background); justify-content: space-between; flex-wrap: wrap; }
.theme-card p { margin-top: var(--g-spacing-2); font-size: 12px; }
.page-footer { display: flex; justify-content: space-between; gap: var(--g-spacing-4); color: var(--g-color-text-hint); padding-top: var(--g-spacing-6); font-size: 11px; }
.page-footer > span:first-child { display: flex; align-items: center; gap: var(--g-spacing-2); }
.empty-chart { height: 100%; display: flex; flex-direction: column; align-items: center; justify-content: center; gap: var(--g-spacing-4); text-align: center; }
.data-table-wrap { max-height: 360px; overflow: auto; border-top: 1px solid var(--g-color-line-generic); }
table { width: 100%; border-collapse: collapse; font-size: 12px; font-variant-numeric: tabular-nums; }
caption { text-align: left; padding: var(--g-spacing-4) var(--g-spacing-7); color: var(--g-color-text-secondary); }
th, td { padding: var(--g-spacing-3) var(--g-spacing-7); text-align: right; white-space: nowrap; border-bottom: 1px solid var(--g-color-line-generic); }
