  .metric-value { flex-wrap: nowrap; gap: var(--g-spacing-3); margin: var(--g-spacing-2) 0; }
  .metric-unit { width: auto; }
  .chart-heading { flex-direction: column; align-items: flex-start; padding: var(--g-spacing-5); }
