  .date-range { padding-left: var(--g-spacing-2); }
  .chart-axis-caption { margin-left: var(--g-spacing-5); }
  .chart-container { height: 290px; margin: 0 var(--g-spacing-2) var(--g-spacing-3); }
  .chart-footer { padding: var(--g-spacing-3) var(--g-spacing-4); flex-wrap: wrap; }
  .chart-tip { font-size: 11px; }
